    )
ON CONFLICT (id_rol, id_permiso) DO NOTHING;

INSERT INTO tbl_empleado (
    nombre_emple,
    estado_emple,
    correo_emple,
    id_rol
)
SELECT
    'admin',
    'ACTIVO',
    'cestradae5@miumg.edu.gt',
    rol.id_rol
FROM tbl_rol AS rol
WHERE rol.codigo = 'ADMINISTRADOR_SISTEMA'
ON CONFLICT (correo_emple) DO UPDATE
SET
    nombre_emple = EXCLUDED.nombre_emple,
    estado_emple = EXCLUDED.estado_emple,
    id_rol = EXCLUDED.id_rol;

DO $$
DECLARE
    permisos_sin_asignar BIGINT;
BEGIN
    SELECT COUNT(*)
    INTO permisos_sin_asignar
    FROM tbl_permiso AS permiso
    WHERE NOT EXISTS (
        SELECT 1
        FROM tbl_rol AS rol
        INNER JOIN tbl_rol_permiso AS rol_permiso
            ON rol_permiso.id_rol = rol.id_rol
        WHERE rol.codigo = 'ADMINISTRADOR_SISTEMA'
          AND rol_permiso.id_permiso = permiso.id_permiso
    );

    IF permisos_sin_asignar <> 0 THEN
        RAISE EXCEPTION
            'El administrador del sistema no tiene asignados todos los permisos existentes';
    END IF;
END;
$$;

-- Infraestructura del sistema de transporte.
-- Creation flow: Municipalidad -> Linea -> Parada/Estacion -> Acceso.
-- A linea can exist before any parqueo, parada or estacion. Tables are
-- declared in FK dependency order (parqueo precedes linea because
-- tbl_linea.id_parqueo still references it).
CREATE TABLE IF NOT EXISTS tbl_municipalidad (
    id_municipalidad BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_municipalidad VARCHAR(120) NOT NULL UNIQUE,
    departamento VARCHAR(60) NOT NULL,
    estado_municipalidad VARCHAR(20) NOT NULL DEFAULT 'ACTIVA' CHECK (estado_municipalidad IN ('ACTIVA', 'INACTIVA'))
);

-- A parqueo is standalone (no FK to estacion); one parqueo can serve
-- several lineas through tbl_linea.id_parqueo.
CREATE TABLE IF NOT EXISTS tbl_parqueo (
    id_parqueo BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_parqueo VARCHAR(120) NOT NULL,
    tipo_parqueo VARCHAR(50) NOT NULL,
    direccion TEXT NOT NULL,
    latitud DECIMAL(10,8) NOT NULL CHECK (latitud BETWEEN -90 AND 90),
    longitud DECIMAL(11,8) NOT NULL CHECK (longitud BETWEEN -180 AND 180),
    capacidad_unidades INTEGER NOT NULL CHECK (capacidad_unidades >= 0),
    estado_parqueo VARCHAR(30) NOT NULL
);

-- id_parqueo is nullable: the linea is created first and its parqueo is
-- assigned later.
CREATE TABLE IF NOT EXISTS tbl_linea (
    id_linea BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_linea VARCHAR(20) NOT NULL UNIQUE,
    nombre_linea VARCHAR(120) NOT NULL,
    color_hex VARCHAR(7) NOT NULL,
    estado_linea VARCHAR(20) NOT NULL CHECK (estado_linea IN ('ACTIVA', 'INACTIVA')),
    tipo_recorrido VARCHAR(20) NOT NULL CHECK (tipo_recorrido IN ('CIRCULAR', 'LINEAL')),
    id_parqueo BIGINT,
    FOREIGN KEY (id_parqueo) REFERENCES tbl_parqueo (id_parqueo)
);

-- Linea <-> Municipalidad is N:M.
CREATE TABLE IF NOT EXISTS tbl_linea_municipalidad (
    id_linea BIGINT NOT NULL,
    id_municipalidad BIGINT NOT NULL,
    PRIMARY KEY (id_linea, id_municipalidad),
    FOREIGN KEY (id_linea) REFERENCES tbl_linea (id_linea),
    FOREIGN KEY (id_municipalidad) REFERENCES tbl_municipalidad (id_municipalidad)
);

CREATE TABLE IF NOT EXISTS tbl_parada (
    id_parada BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_parada VARCHAR(120) NOT NULL,
    latitud DECIMAL(10,8) NOT NULL CHECK (latitud BETWEEN -90 AND 90),
    longitud DECIMAL(11,8) NOT NULL CHECK (longitud BETWEEN -180 AND 180),
    estado_parada VARCHAR(20) NOT NULL CHECK (estado_parada IN ('ACTIVA', 'CERRADA', 'MANTENIMIENTO')),
    capacidad_pasajeros INTEGER NOT NULL DEFAULT 100 CHECK (capacidad_pasajeros > 0),
    personas_en_parada INTEGER NOT NULL DEFAULT 0 CHECK (personas_en_parada >= 0)
);

-- An estacion is a 1:1 extension of a parada.
CREATE TABLE IF NOT EXISTS tbl_estacion (
    id_estacion BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_estacion VARCHAR(120) NOT NULL,
    latitud DECIMAL(10,8) NOT NULL CHECK (latitud BETWEEN -90 AND 90),
    longitud DECIMAL(11,8) NOT NULL CHECK (longitud BETWEEN -180 AND 180),
    estado_estacion VARCHAR(30) NOT NULL,
    id_parada BIGINT NOT NULL UNIQUE,
    FOREIGN KEY (id_parada) REFERENCES tbl_parada (id_parada)
);

-- Accesos (entrances) belong to a parada.
CREATE TABLE IF NOT EXISTS tbl_acceso (
    id_acceso BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_parada BIGINT NOT NULL,
    nombre_acceso VARCHAR(120) NOT NULL,
    latitud DECIMAL(10,8) NOT NULL CHECK (latitud BETWEEN -90 AND 90),
    longitud DECIMAL(11,8) NOT NULL CHECK (longitud BETWEEN -180 AND 180),
    tipo_acceso VARCHAR(20) NOT NULL CHECK (tipo_acceso IN ('PEATONAL', 'RAMPA', 'ESCALERA', 'ELEVADOR')),
    estado_acceso VARCHAR(20) NOT NULL DEFAULT 'HABILITADO' CHECK (estado_acceso IN ('HABILITADO', 'DESHABILITADO')),
    FOREIGN KEY (id_parada) REFERENCES tbl_parada (id_parada)
);

CREATE TABLE IF NOT EXISTS tbl_linea_parada (
    id_linea_parada BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    orden INTEGER NOT NULL CHECK (orden > 0),
    minutos_hasta_siguiente INTEGER NOT NULL CHECK (minutos_hasta_siguiente >= 0),
    id_parada BIGINT NOT NULL,
    id_linea BIGINT NOT NULL,
    FOREIGN KEY (id_parada) REFERENCES tbl_parada (id_parada),
    FOREIGN KEY (id_linea) REFERENCES tbl_linea (id_linea),
    UNIQUE (id_linea, orden),
    UNIQUE (id_linea, id_parada)
);

CREATE TABLE IF NOT EXISTS tbl_estacion_linea (
    id_linea BIGINT NOT NULL,
    id_estacion BIGINT NOT NULL,
    tipo_punto VARCHAR(20) NOT NULL CHECK (tipo_punto IN ('PRINCIPAL', 'CONTROL', 'APOYO')),
    estado_asignacion VARCHAR(30) NOT NULL CHECK (estado_asignacion IN ('ACTIVA', 'INACTIVA')),
    PRIMARY KEY (id_linea, id_estacion),
    FOREIGN KEY (id_linea) REFERENCES tbl_linea (id_linea),
    FOREIGN KEY (id_estacion) REFERENCES tbl_estacion (id_estacion)
);

CREATE TABLE IF NOT EXISTS tbl_afectacion (
    id_afectacion BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_afectacion VARCHAR(50) NOT NULL,
    motivo TEXT NOT NULL,
    fecha_inicio TIMESTAMPTZ NOT NULL,
    fecha_fin TIMESTAMPTZ,
    estado_afectacion VARCHAR(30) NOT NULL,
    id_parada BIGINT,
    id_estacion BIGINT,
    FOREIGN KEY (id_parada) REFERENCES tbl_parada (id_parada),
    FOREIGN KEY (id_estacion) REFERENCES tbl_estacion (id_estacion),
    CHECK (fecha_fin IS NULL OR fecha_fin >= fecha_inicio),
    CHECK ((id_parada IS NOT NULL) <> (id_estacion IS NOT NULL))
);

CREATE TABLE IF NOT EXISTS tbl_asignacion_estacion (
    id_asignacion_estacion BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_asignacion TIMESTAMPTZ NOT NULL,
    estado_asignacion VARCHAR(30) NOT NULL CHECK (estado_asignacion IN ('ACTIVA', 'INACTIVA')),
    id_empleado BIGINT NOT NULL,
    id_estacion BIGINT NOT NULL,
    FOREIGN KEY (id_empleado) REFERENCES tbl_empleado (id_emple),
    FOREIGN KEY (id_estacion) REFERENCES tbl_estacion (id_estacion)
);

-- Flota y asignaciones operativas.
CREATE TABLE IF NOT EXISTS tbl_unidad (
    id_unidad BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_placa VARCHAR(20) NOT NULL UNIQUE,
    marca VARCHAR(60) NOT NULL,
    modelo VARCHAR(60) NOT NULL,
    anio INTEGER NOT NULL,
    capacidad_pasajeros INTEGER NOT NULL CHECK (capacidad_pasajeros > 0),
    estado_unidad VARCHAR(30) NOT NULL CHECK (estado_unidad IN ('DISPONIBLE', 'EN_SERVICIO', 'MANTENIMIENTO', 'FUERA_DE_SERVICIO')),
    fecha_registro TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS tbl_asignacion_unidad (
    id_asignacion_unidad BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_asignacion TIMESTAMPTZ NOT NULL,
    fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    id_unidad BIGINT NOT NULL UNIQUE,
    id_linea BIGINT NOT NULL,
    id_linea_parada_actual BIGINT,
    fecha_reporte_ubicacion TIMESTAMPTZ,
    FOREIGN KEY (id_unidad) REFERENCES tbl_unidad (id_unidad),
    FOREIGN KEY (id_linea) REFERENCES tbl_linea (id_linea),
    FOREIGN KEY (id_linea_parada_actual) REFERENCES tbl_linea_parada (id_linea_parada)
);

CREATE TABLE IF NOT EXISTS tbl_asignacion_piloto (
    id_asignacion_piloto BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_asignacion TIMESTAMPTZ NOT NULL,
    fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    id_empleado BIGINT NOT NULL UNIQUE,
    id_unidad BIGINT NOT NULL UNIQUE,
    FOREIGN KEY (id_empleado) REFERENCES tbl_empleado (id_emple),
    FOREIGN KEY (id_unidad) REFERENCES tbl_unidad (id_unidad)
);

-- Operación: alertas, novedades, historial y afectaciones.
CREATE TABLE IF NOT EXISTS tbl_alerta (
    id_alerta BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_alerta VARCHAR(50) NOT NULL,
    tipo_origen VARCHAR(30) NOT NULL CHECK (tipo_origen IN ('UNIDAD', 'ESTACION')),
    tipo_destino VARCHAR(30) NOT NULL CHECK (tipo_destino IN ('CENTRAL', 'ESTACION')),
    estado_alerta VARCHAR(30) NOT NULL CHECK (estado_alerta IN ('PENDIENTE', 'RECIBIDA', 'EN_ATENCION', 'RESUELTA')),
    fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    id_unidad BIGINT,
    id_estacion_origen BIGINT,
    id_estacion_destino BIGINT,
    id_empleado BIGINT,
    FOREIGN KEY (id_unidad) REFERENCES tbl_unidad (id_unidad),
    FOREIGN KEY (id_estacion_origen) REFERENCES tbl_estacion (id_estacion),
    FOREIGN KEY (id_estacion_destino) REFERENCES tbl_estacion (id_estacion),
    FOREIGN KEY (id_empleado) REFERENCES tbl_empleado (id_emple)
);

CREATE TABLE IF NOT EXISTS tbl_novedad (
    id_novedad BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_novedad VARCHAR(50) NOT NULL,
    titulo VARCHAR(200) NOT NULL,
    descripcion TEXT NOT NULL,
    estado_novedad VARCHAR(30) NOT NULL CHECK (estado_novedad IN ('BORRADOR', 'PUBLICADA', 'DESACTIVADA')),
    fecha_inicio TIMESTAMPTZ NOT NULL,
    fecha_fin TIMESTAMPTZ,
    fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    id_empleado BIGINT NOT NULL,
    FOREIGN KEY (id_empleado) REFERENCES tbl_empleado (id_emple),
    CHECK (fecha_fin IS NULL OR fecha_fin >= fecha_inicio)
);

CREATE TABLE IF NOT EXISTS tbl_historial_estado (
    id_historial_estado BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    estado_anterior VARCHAR(30) NOT NULL,
    estado_nuevo VARCHAR(30) NOT NULL,
    observacion TEXT,
    fecha_cambio TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    id_alerta BIGINT,
    id_novedad BIGINT,
    id_empleado BIGINT NOT NULL,
    FOREIGN KEY (id_alerta) REFERENCES tbl_alerta (id_alerta),
    FOREIGN KEY (id_novedad) REFERENCES tbl_novedad (id_novedad),
    FOREIGN KEY (id_empleado) REFERENCES tbl_empleado (id_emple),
    CHECK ((id_alerta IS NOT NULL)::int + (id_novedad IS NOT NULL)::int = 1)
);

CREATE TABLE IF NOT EXISTS tbl_afectacion_operativa (
    id_afectacion_op BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_alerta BIGINT,
    id_novedad BIGINT,
    id_linea BIGINT,
    id_estacion BIGINT,
    id_unidad BIGINT,
    FOREIGN KEY (id_alerta) REFERENCES tbl_alerta (id_alerta),
    FOREIGN KEY (id_novedad) REFERENCES tbl_novedad (id_novedad),
    FOREIGN KEY (id_linea) REFERENCES tbl_linea (id_linea),
    FOREIGN KEY (id_estacion) REFERENCES tbl_estacion (id_estacion),
    FOREIGN KEY (id_unidad) REFERENCES tbl_unidad (id_unidad),
    CHECK (
    (id_linea IS NOT NULL)::int + 
    (id_estacion IS NOT NULL)::int + 
    (id_unidad IS NOT NULL)::int = 1
)
);

-- Pago exprés: recargas QPayPro (bloque independiente, sin FK a empleado).
CREATE TABLE IF NOT EXISTS tbl_tarjeta_ciudadana (
    id_tarjeta_ciudadana BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_tarjeta VARCHAR(50) NOT NULL UNIQUE,
    saldo NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (saldo >= 0),
    estado_tarjeta VARCHAR(30) NOT NULL CHECK (estado_tarjeta IN ('ACTIVA', 'BLOQUEADA', 'VENCIDA', 'ANULADA'))
);

CREATE TABLE IF NOT EXISTS tbl_transaccion_pago (
    id_transaccion_pago BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tarjeta_ciudadana BIGINT NOT NULL,
    referencia_pago VARCHAR(100) NOT NULL UNIQUE,
    id_transaccion_qpaypro VARCHAR(100) UNIQUE,
    monto_pago NUMERIC(12,2) NOT NULL CHECK (monto_pago > 0),
    moneda CHAR(3) NOT NULL DEFAULT 'GTQ',
    estado_pago VARCHAR(30) NOT NULL CHECK (estado_pago IN ('INICIADA', 'PENDIENTE_AUTENTICACION', 'APROBADA', 'RECHAZADA', 'ERROR', 'EXPIRADA')),
    codigo_respuesta VARCHAR(20),
    mensaje_respuesta TEXT,
    numero_autorizacion VARCHAR(50),
    fecha_transaccion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_confirmacion TIMESTAMPTZ,
    FOREIGN KEY (id_tarjeta_ciudadana) REFERENCES tbl_tarjeta_ciudadana (id_tarjeta_ciudadana)
);

CREATE TABLE IF NOT EXISTS tbl_recarga (
    id_recarga BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_transaccion_pago BIGINT NOT NULL UNIQUE,
    id_tarjeta_ciudadana BIGINT NOT NULL,
    monto_recarga NUMERIC(12,2) NOT NULL CHECK (monto_recarga > 0),
    fecha_recarga TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_transaccion_pago) REFERENCES tbl_transaccion_pago (id_transaccion_pago),
    FOREIGN KEY (id_tarjeta_ciudadana) REFERENCES tbl_tarjeta_ciudadana (id_tarjeta_ciudadana)
);

CREATE TABLE IF NOT EXISTS tbl_comprobante (
    id_comprobante BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_recarga BIGINT NOT NULL UNIQUE,
    numero_comprobante VARCHAR(50) NOT NULL UNIQUE,
    fecha_emision TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_recarga) REFERENCES tbl_recarga (id_recarga)
);

-- Conteo de pasajeros (ridership). Cada pasada por una talanquera es un
-- evento inmutable; la ocupación de una parada (sea o no estación) se
-- calcula a partir de los eventos, nunca se guarda como contador.
CREATE TABLE IF NOT EXISTS tbl_evento_talanquera (
    id_evento_talanquera BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_parada BIGINT NOT NULL,
    id_tarjeta_ciudadana BIGINT NOT NULL,
    tipo_evento VARCHAR(10) NOT NULL CHECK (tipo_evento IN ('ENTRADA', 'SALIDA')),
    monto_cobrado NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (monto_cobrado >= 0),
    clave_idempotencia VARCHAR(64) UNIQUE,
    fecha_evento TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_parada) REFERENCES tbl_parada (id_parada),
    FOREIGN KEY (id_tarjeta_ciudadana) REFERENCES tbl_tarjeta_ciudadana (id_tarjeta_ciudadana)
);

-- Reporte del piloto en una parada: cuántos bajaron y cuántos subieron. El
-- bus solo traslada pasajeros entre paradas; la ocupación de la unidad es la
-- resultante de su último reporte.
CREATE TABLE IF NOT EXISTS tbl_parada_unidad (
    id_parada_unidad BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_unidad BIGINT NOT NULL,
    id_parada BIGINT NOT NULL,
    id_empleado BIGINT,
    fecha_reporte TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    subieron INTEGER NOT NULL DEFAULT 0 CHECK (subieron >= 0),
    bajaron INTEGER NOT NULL DEFAULT 0 CHECK (bajaron >= 0),
    ocupacion_resultante INTEGER NOT NULL CHECK (ocupacion_resultante >= 0),
    minutos_espera_extra INTEGER NOT NULL DEFAULT 0 CHECK (minutos_espera_extra >= 0),
    FOREIGN KEY (id_unidad) REFERENCES tbl_unidad (id_unidad),
    FOREIGN KEY (id_parada) REFERENCES tbl_parada (id_parada),
    FOREIGN KEY (id_empleado) REFERENCES tbl_empleado (id_emple)
);

-- Auditoría y bitácora de cambios.
CREATE TABLE IF NOT EXISTS tbl_bitacora (
    id_bitacora BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_hora TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    modulo VARCHAR(60) NOT NULL,
    accion VARCHAR(80) NOT NULL,
    entidad_tipo VARCHAR(60) NOT NULL,
    entidad_id BIGINT,
    resultado VARCHAR(30) NOT NULL CHECK (resultado IN ('EXITOSO', 'FALLIDO', 'ERROR')),
    id_empleado BIGINT,
    detalle JSONB,
    FOREIGN KEY (id_empleado) REFERENCES tbl_empleado (id_emple)
);

-- ---------------------------------------------------------------------------
-- Evolución de bases existentes
-- ---------------------------------------------------------------------------
-- `CREATE TABLE IF NOT EXISTS` es un no-op cuando la tabla ya existe: correr
-- este archivo contra una base creada con una versión anterior de init.sql NO
-- agrega columnas nuevas. Para que una base existente alcance el esquema de
-- arriba sin scripts separados, cada columna agregada después del esquema
-- inicial se declara aquí con su ALTER idempotente.
--
-- `IF NOT EXISTS` los hace seguros de re-ejecutar: correr init.sql completo
-- varias veces sobre la misma base no falla ni altera nada.
--
-- tbl_bitacora.detalle JSONB — nullable, sin default. Requisito del módulo
-- fleet: cada mutación registra su payload estructurado. Las filas de
-- auditoría de auth escritas antes de esta columna conservan detalle = NULL.

ALTER TABLE tbl_bitacora ADD COLUMN IF NOT EXISTS detalle JSONB;

-- tbl_bitacora.id_empleado / entidad_id — nullable. Un login fallido se
-- registra solo como "ocurrió un intento": sin empleado, sin entidad y sin el
-- correo intentado. DROP NOT NULL es idempotente (no falla si ya es nullable),
-- así que las bases existentes se actualizan al re-aplicar este archivo.

ALTER TABLE tbl_bitacora ALTER COLUMN id_empleado DROP NOT NULL;
ALTER TABLE tbl_bitacora ALTER COLUMN entidad_id DROP NOT NULL;

-- tbl_empleado: perfil de RR. HH. del módulo Personal. Todas las columnas son
-- nullable para que las filas existentes (p. ej. el admin del seed) sigan
-- funcionando. La API exige el DPI como obligatorio; la columna queda nullable
-- solo por compatibilidad con filas legacy. El índice único parcial garantiza
-- que el DPI no se repita cuando está presente.

ALTER TABLE tbl_empleado ADD COLUMN IF NOT EXISTS telefono_emple VARCHAR(20);
ALTER TABLE tbl_empleado ADD COLUMN IF NOT EXISTS dpi_emple VARCHAR(13);
ALTER TABLE tbl_empleado ADD COLUMN IF NOT EXISTS fecha_ingreso_emple DATE;
ALTER TABLE tbl_empleado ADD COLUMN IF NOT EXISTS direccion_emple VARCHAR(255);
ALTER TABLE tbl_empleado ADD COLUMN IF NOT EXISTS licencia_emple VARCHAR(30);
ALTER TABLE tbl_empleado ADD COLUMN IF NOT EXISTS historial_educativo_emple TEXT;
ALTER TABLE tbl_empleado ADD COLUMN IF NOT EXISTS idiomas_emple TEXT;

CREATE UNIQUE INDEX IF NOT EXISTS idx_empleado_dpi ON tbl_empleado (dpi_emple) WHERE dpi_emple IS NOT NULL;

-- tbl_alerta.id_linea — nullable. Línea desde la que se envió la alerta,
-- fijada al crearla (la línea asignada a la unidad en ese momento). Una
-- estación solo ve las alertas de sus líneas ACTIVAS. La columna se agrega y
-- las alertas existentes se completan una sola vez, con la línea actual de su
-- unidad; las de unidades sin línea quedan en NULL (solo visibles en la vista
-- central, en "Sin línea"). Re-aplicar este archivo no repite el backfill.

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = current_schema()
           AND table_name = 'tbl_alerta'
           AND column_name = 'id_linea'
    ) THEN
        ALTER TABLE tbl_alerta
            ADD COLUMN id_linea BIGINT REFERENCES tbl_linea (id_linea);
        UPDATE tbl_alerta a
           SET id_linea = au.id_linea
          FROM tbl_asignacion_unidad au
         WHERE au.id_unidad = a.id_unidad;
    END IF;
END
$$;


-- tbl_alerta.id_empleado — nullable. Las alertas que genera el sistema (por
-- ejemplo, capacidad de estación al pasar una talanquera) no tienen autor.

ALTER TABLE tbl_alerta ALTER COLUMN id_empleado DROP NOT NULL;

-- tbl_evento_talanquera.clave_idempotencia — nullable, UNIQUE. Clave que
-- envía la talanquera para que un reintento de la misma pasada no cobre ni
-- registre dos veces. Las pasadas sin clave no se deduplican.

ALTER TABLE tbl_evento_talanquera ADD COLUMN IF NOT EXISTS clave_idempotencia VARCHAR(64) UNIQUE;

-- Conteo por parada. El conteo, la capacidad y la alerta del 150% son de la
-- parada; una estación usa los de su parada (tbl_estacion.id_parada).
--
-- tbl_parada.capacidad_pasajeros — personas que la parada admite esperando.
-- Si la estación ya tenía capacidad propia (versión anterior de este
-- archivo), se copia una sola vez a su parada y la columna de la estación se
-- elimina. Eventos de talanquera y detenciones de unidades pasan de
-- id_estacion a id_parada, convertidos a través de tbl_estacion.id_parada.
-- Las alertas de capacidad guardan la parada en tbl_alerta.id_parada_origen.

ALTER TABLE tbl_parada ADD COLUMN IF NOT EXISTS capacidad_pasajeros INTEGER NOT NULL DEFAULT 100 CHECK (capacidad_pasajeros > 0);

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = current_schema()
           AND table_name = 'tbl_estacion' AND column_name = 'capacidad_pasajeros'
    ) THEN
        UPDATE tbl_parada p
           SET capacidad_pasajeros = e.capacidad_pasajeros
          FROM tbl_estacion e
         WHERE e.id_parada = p.id_parada;
        ALTER TABLE tbl_estacion DROP COLUMN capacidad_pasajeros;
    END IF;

    IF EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = current_schema()
           AND table_name = 'tbl_evento_talanquera' AND column_name = 'id_estacion'
    ) THEN
        ALTER TABLE tbl_evento_talanquera
            ADD COLUMN id_parada BIGINT REFERENCES tbl_parada (id_parada);
        UPDATE tbl_evento_talanquera ev
           SET id_parada = e.id_parada
          FROM tbl_estacion e
         WHERE e.id_estacion = ev.id_estacion;
        ALTER TABLE tbl_evento_talanquera ALTER COLUMN id_parada SET NOT NULL;
        ALTER TABLE tbl_evento_talanquera DROP COLUMN id_estacion;
    END IF;

    IF EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = current_schema()
           AND table_name = 'tbl_parada_unidad' AND column_name = 'id_estacion'
    ) THEN
        ALTER TABLE tbl_parada_unidad
            ADD COLUMN id_parada BIGINT REFERENCES tbl_parada (id_parada);
        UPDATE tbl_parada_unidad pu
           SET id_parada = e.id_parada
          FROM tbl_estacion e
         WHERE e.id_estacion = pu.id_estacion;
        ALTER TABLE tbl_parada_unidad ALTER COLUMN id_parada SET NOT NULL;
        ALTER TABLE tbl_parada_unidad DROP COLUMN id_estacion;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = current_schema()
           AND table_name = 'tbl_alerta' AND column_name = 'id_parada_origen'
    ) THEN
        ALTER TABLE tbl_alerta
            ADD COLUMN id_parada_origen BIGINT REFERENCES tbl_parada (id_parada);
        UPDATE tbl_alerta a
           SET id_parada_origen = e.id_parada
          FROM tbl_estacion e
         WHERE e.id_estacion = a.id_estacion_origen
           AND a.tipo_alerta = 'CAPACIDAD_ESTACION';
    END IF;
END
$$;

CREATE INDEX IF NOT EXISTS idx_evento_talanquera_parada
    ON tbl_evento_talanquera (id_parada, tipo_evento, fecha_evento);
CREATE INDEX IF NOT EXISTS idx_parada_unidad_parada
    ON tbl_parada_unidad (id_parada);

-- tbl_parada_unidad pasa de "llegada/salida de la unidad" a "reporte del
-- piloto" (bajaron y subieron en una parada). Se elimina el estado de parada
-- abierta (fecha_salida, ocupacion_llegada y su índice único), fecha_llegada
-- pasa a llamarse fecha_reporte y se guarda el piloto que reportó. Las filas
-- existentes se conservan como reportes.

DROP INDEX IF EXISTS idx_parada_unidad_abierta;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = current_schema()
           AND table_name = 'tbl_parada_unidad' AND column_name = 'fecha_llegada'
    ) THEN
        ALTER TABLE tbl_parada_unidad RENAME COLUMN fecha_llegada TO fecha_reporte;
    END IF;
END
$$;

ALTER TABLE tbl_parada_unidad DROP COLUMN IF EXISTS fecha_salida;
ALTER TABLE tbl_parada_unidad DROP COLUMN IF EXISTS ocupacion_llegada;
ALTER TABLE tbl_parada_unidad ADD COLUMN IF NOT EXISTS id_empleado BIGINT REFERENCES tbl_empleado (id_emple);

CREATE INDEX IF NOT EXISTS idx_parada_unidad_unidad
    ON tbl_parada_unidad (id_unidad, fecha_reporte);

-- tbl_parada.personas_en_parada — personas esperando ahora en la parada.
-- Lo cambian, con la fila de la parada bloqueada y en la misma transacción
-- que guarda el evento: la talanquera (+1 entrada, -1 salida) y el reporte
-- del piloto (+bajaron, -subieron), nunca por debajo de 0. Al agregar la
-- columna a una base existente se calcula una vez desde los eventos y los
-- reportes guardados.

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = current_schema()
           AND table_name = 'tbl_parada' AND column_name = 'personas_en_parada'
    ) THEN
        ALTER TABLE tbl_parada
            ADD COLUMN personas_en_parada INTEGER NOT NULL DEFAULT 0 CHECK (personas_en_parada >= 0);
        UPDATE tbl_parada p
           SET personas_en_parada = GREATEST(0,
                 (SELECT COUNT(*) FILTER (WHERE tipo_evento = 'ENTRADA')
                       - COUNT(*) FILTER (WHERE tipo_evento = 'SALIDA')
                    FROM tbl_evento_talanquera ev WHERE ev.id_parada = p.id_parada)
               + (SELECT COALESCE(SUM(pu.bajaron - pu.subieron), 0)
                    FROM tbl_parada_unidad pu WHERE pu.id_parada = p.id_parada));
    END IF;
END
$$;

-- ===========================================================================
-- Datos iniciales: snapshot de la base local `transmetro` (2026-10-19)
-- ===========================================================================
-- Todo lo de abajo es idempotente: cada INSERT usa ON CONFLICT DO NOTHING,
-- así que volver a ejecutar init.sql no duplica ni pisa datos existentes.
-- - Roles, permisos y rol-permiso NO se copian: los define el bloque
--   canónico de arriba. Los id_permiso de la base de origen no coinciden
--   con los de una corrida limpia, y sus 4 permisos heredados sin uso
--   (ALERTAS_ENVIAR_ATENDER, ESTACION_ASIGNADA_GESTIONAR, PERFIL_CONSULTAR,
--   UNIDAD_ASIGNADA_CONTROLAR) quedan fuera a propósito.
-- - Las secuencias se mueven a MAX(id) + 1 (nunca hacia atrás).
-- - tbl_sesion no se incluye (sesiones efímeras).
-- - tbl_bitacora no se incluye (auditoría del entorno local, no es dato semilla).
-- - Al final se crea la cuenta de la docente revisora y las personas de demo
--   del cambio de rol (docs/demo-role-switch.md).

