-- Cuenta de la docente revisora y personas de demo (cambio de rol "Ver como").
-- 1. Reviewer account (emails are matched case-insensitively at login).
INSERT INTO tbl_empleado (nombre_emple, estado_emple, correo_emple, id_rol)
SELECT 'Docente revisor', 'ACTIVO', 'nportillop1@miumg.edu.gt', rol.id_rol
FROM tbl_rol AS rol
WHERE rol.codigo = 'ADMINISTRADOR_SISTEMA'
ON CONFLICT (correo_emple) DO UPDATE
SET estado_emple = 'ACTIVO',
    id_rol = EXCLUDED.id_rol;

-- 2. Demo personas, one per operational role.
INSERT INTO tbl_empleado (nombre_emple, estado_emple, correo_emple, id_rol)
SELECT persona.nombre, 'ACTIVO', persona.correo, rol.id_rol
FROM (VALUES
    ('Demo Piloto', 'demo.piloto@transmetro.invalid', 'PILOTO'),
    ('Demo Guardia', 'demo.guardia@transmetro.invalid', 'GUARDIA'),
    ('Demo Operador de estación', 'demo.operador.estacion@transmetro.invalid', 'OPERADOR_ESTACION'),
    ('Demo Operador central', 'demo.operador.central@transmetro.invalid', 'OPERADOR_CENTRAL')
) AS persona (nombre, correo, codigo)
INNER JOIN tbl_rol AS rol ON rol.codigo = persona.codigo
ON CONFLICT (correo_emple) DO UPDATE
SET estado_emple = 'ACTIVO',
    id_rol = EXCLUDED.id_rol;

-- 3a. Station for the demo station operator (an operator holds at most one
-- ACTIVA row). Prefers a station nobody operates yet.
INSERT INTO tbl_asignacion_estacion (fecha_asignacion, estado_asignacion, id_empleado, id_estacion)
SELECT CURRENT_TIMESTAMP, 'ACTIVA', empleado.id_emple, estacion.id_estacion
FROM tbl_empleado AS empleado
CROSS JOIN LATERAL (
    SELECT candidata.id_estacion
    FROM tbl_estacion AS candidata
    ORDER BY EXISTS (
                 SELECT 1 FROM tbl_asignacion_estacion AS ocupada
                 WHERE ocupada.id_estacion = candidata.id_estacion
                   AND ocupada.estado_asignacion = 'ACTIVA'
             ),
             candidata.id_estacion
    LIMIT 1
) AS estacion
WHERE empleado.correo_emple = 'demo.operador.estacion@transmetro.invalid'
  AND NOT EXISTS (
      SELECT 1 FROM tbl_asignacion_estacion AS actual
      WHERE actual.id_empleado = empleado.id_emple
        AND actual.estado_asignacion = 'ACTIVA'
  );

-- 3b. Unit for the demo pilot: an operating unit (assigned to a line) that
-- has no pilot yet. Skipped when every unit already has a pilot; the switch
-- then falls back to any other pilot that has a unit.
INSERT INTO tbl_asignacion_piloto (fecha_asignacion, fecha_actualizacion, id_empleado, id_unidad)
SELECT CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, empleado.id_emple, unidad.id_unidad
FROM tbl_empleado AS empleado
CROSS JOIN LATERAL (
    SELECT asignacion.id_unidad
    FROM tbl_asignacion_unidad AS asignacion
    WHERE NOT EXISTS (
        SELECT 1 FROM tbl_asignacion_piloto AS piloto
        WHERE piloto.id_unidad = asignacion.id_unidad
    )
    ORDER BY asignacion.id_unidad
    LIMIT 1
) AS unidad
WHERE empleado.correo_emple = 'demo.piloto@transmetro.invalid'
  AND NOT EXISTS (
      SELECT 1 FROM tbl_asignacion_piloto AS actual
      WHERE actual.id_empleado = empleado.id_emple
  );

COMMIT;
